end

function C:ShowPager(page)
  local num = 0
  if self.status == "go" then
    return
  end
  if self.status == "alpha" then
    num = self.alphaMaxPage
  end
  if self.status == "beta" then
    num = self.betaMaxPage
  end
  self.nowPage = page
  self:CleanPaging()
  do
    local i = 0
    while i < num do
      do
        if i == page then
          Object.Instantiate(self.PageNowPrefab, self.PagingParent)
          goto continue
        end
        local gameObject = Object.Instantiate(self.PagePrefab, self.PagingParent)
        local index = i
        gameObject:GetComponent("Button"):OnClickAsObservable():Subscribe(function(_)
          self:PageTo(index)
        end):AddTo(gameObject)
      end
      ::continue::
      i = i + 1
    end
  end
end

function C:CleanPaging()
  do
    local num = self.PagingParent.childCount - 1
    while num >= 0 do
      Object.Destroy(self.PagingParent:GetChild(num).gameObject)
      num = num - 1
    end
  end
end

function C:PageTo(page)
  if self.status == "alpha" then
    self:ShowAlphaChip(page)
  end
end

function C:Choosed(alpha, level)
  self.ChoosedAlphaType = alpha
  self.level = level
  self.AlphaButton.gameObject:SetActive(true)
  self.AlphaButton.gameObject:GetComponent("NetaChipAlpha"):ShowType(alpha, level, true)
  self.backButton:OnClickAsObservable():Subscribe(function(_)
    if EventManager.isTestScene then
      self:ShowAlphaLevelChip()
    else
      self:ShowAlphaChip(IDIV(ENUMV("AlphaType", alpha), self.MAXCHIPSHOWING))
    end
  end):AddTo(self.AlphaButton)
  self:ChooseNext()
end

function C:ChooseNext()
  if self.ChoosedAlphaType == "none" then
    self:ShowAlphaChip(0)
  else
    self:ShowKaimaku()
  end
end

